Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -33,4 +33,38 @@
 <div class="controls"><div class="mobile-control stick" id="stick"><div class="nub" id="nub"></div></div><div class="mobile-control action-stack"><button class="action-btn fire-btn" id="fireBtn">FIRE</button><button class="action-btn shield-btn" id="shieldBtn">◉</button></div></div>
 <div class="overlay" id="overlay"><section class="modal"><div class="eyebrow" id="modalEyebrow">OPERATION // BLUEWATER</div><h1 id="modalTitle">Hold the<br>horizon.</h1><p id="modalCopy">Command the carrier and its five escorts. Outlast five escalating waves of raiders, dive craft, and rival fleets.</p><div class="key-guide" id="keyGuide"><div class="key"><strong>WASD / ARROWS</strong><span>Steer the carrier</span></div><div class="key"><strong>SPACE / FIRE</strong><span>Auto-target attackers</span></div><div class="key"><strong>E / ◉</strong><span>Release Aegis pulse</span></div><div class="key"><strong>KEEP MOVING</strong><span>Protect your hull</span></div></div><button class="primary" id="startBtn">DEPLOY FLEET&nbsp; →</button><p class="small-note" id="modalNote">TOUCH CONTROLS AVAILABLE · LANDSCAPE OR PORTRAIT</p></section></div>
 </div>
 <script>
+(()=>{
+'use strict';
+const canvas=document.getElementById('ocean'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id);
+const ui={overlay:$('overlay'),title:$('modalTitle'),copy:$('modalCopy'),eyebrow:$('modalEyebrow'),guide:$('keyGuide'),start:$('startBtn'),note:$('modalNote'),hull:$('hullText'),score:$('scoreText'),wave:$('waveText'),mission:$('missionNo'),objective:$('objective'),progress:$('progressFill'),waveInfo:$('waveInfo'),fleet:$('fleetRow'),fleetCaption:$('fleetCaption'),ability:$('abilityHint'),toast:$('toast'),pause:$('pauseBtn'),stick:$('stick'),nub:$('nub'),fire:$('fireBtn'),shield:$('shieldBtn')};
+let W=innerWidth,H=innerHeight,DPR=1,now=0,last=0,scene='title',score=0,wave=0,carrier,escorts=[],enemies=[],shots=[],hostileShots=[],particles=[],pickups=[],spawnQueue=[],spawnTimer=0,intermission=0,elapsed=0,fireHeld=false,keys={},stick={x:0,y:0,id:null,cx:0,cy:0},shieldCooldown=0,shake=0,toastTimer=0,uiTimer=0,serial=0,waterOffset=0;
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),angle=(a,b)=>Math.atan2(b.y-a.y,b.x-a.x),TAU=Math.PI*2;
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0)}
+addEventListener('resize',resize,{passive:true});resize();
+function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.8}
+function startGame(){score=0;wave=0;elapsed=0;carrier={x:W*.5,y:H*.53,r:23,hp:100,maxHp:100,invuln:0,angle:-Math.PI/2,speed:175,fire:0};escorts=[];for(let i=0;i<5;i++)escorts.push({angle:i*TAU/5,orbit:62,hp:100,maxHp:100,fire:rand(.1,1),x:carrier.x,y:carrier.y,r:11});enemies=[];shots=[];hostileShots=[];particles=[];pickups=[];spawnQueue=[];shieldCooldown=0;scene='playing';ui.overlay.classList.add('hidden');nextWave()}
+function nextWave(){wave++;if(wave>5){victory();return}let count=5+wave*3;spawnQueue=[];for(let i=0;i<count;i++){let type=wave>=3&&i%7===6?'sub':(wave>=2&&i%4===2?'plane':'raider');spawnQueue.push({type,delay:i*rand(.55,.9)})}if(wave===3||wave===5)spawnQueue.push({type:'flagship',delay:4});spawnTimer=.8;intermission=0;announce(`WAVE ${String(wave).padStart(2,'0')} INBOUND`);ui.waveInfo.textContent=wave===5?'FLAGSHIP CONTACT EXPECTED':'CONTACTS INBOUND';ui.objective=ui.objective||$('objective');$('objective').textContent=wave===5?'Destroy the rival carrier group.':'Protect the fleet. Clear the waters.'}
+function showEnd(win){scene=win?'won':'lost';ui.overlay.classList.remove('hidden');ui.eyebrow.textContent=win?'OPERATION // COMPLETE':'FLEET // LOST';ui.title.innerHTML=win?'Horizon<br>secured.':'Fleet<br>overrun.';ui.copy.textContent=win?`Five waves broken. The Bluewater group is safe, and the horizon is yours. Final score: ${score.toLocaleString()}.`:`Your carrier has been disabled on wave ${wave}. Rally the escorts and try again. Final score: ${score.toLocaleString()}.`;ui.guide.classList.add('hidden');ui.start.textContent=win?'SAIL AGAIN  →':'REDEPLOY  →';ui.note.textContent='YOUR FLEET IS WAITING';}
+function victory(){showEnd(true)}
+function gameOver(){if(scene!=='playing')return;showEnd(false)}
+ui.start.addEventListener('click',startGame);
+ui.pause.addEventListener('click',()=>{if(scene==='playing')pauseGame();else if(scene==='paused')resumeGame()});
+function pauseGame(){scene='paused';ui.overlay.classList.remove('hidden');ui.eyebrow.textContent='OPERATION // PAUSED';ui.title.innerHTML='Catch your<br>breath.';ui.copy.textContent='The sea can wait. Your fleet is holding position.';ui.guide.classList.add('hidden');ui.start.textContent='RESUME MISSION  →';ui.start.onclick=resumeGame;ui.note.textContent='PRESS ESC OR TAP RESUME'}
+function resumeGame(){if(scene!=='paused')return;scene='playing';ui.overlay.classList.add('hidden');ui.start.onclick=startGame}
+function makeBurst(x,y,color,n=8,power=100){for(let i=0;i<n;i++){let a=rand(0,TAU),v=rand(power*.25,power),life=rand(.25,.65);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life,max:life,size:rand(1.5,4),color})}}
+function spawnEnemy(type){let side=Math.floor(rand(0,4)),x=side===0?rand(0,W):side===1?W+25:side===2?rand(0,W):-25,y=side===0?-25:side===1?rand(0,H):side===2?H+25:rand(0,H);let d={raider:[24,38,2,23],plane:[17,60,1,16],sub:[22,25,3,28],flagship:[48,18,24,95]}[type];enemies.push({id:serial++,type,x,y,r:d[0],speed:d[1],hp:d[2],maxHp:d[2],fire:rand(.8,2),angle:0,phase:rand(0,TAU),flash:0,score:d[3],side:rand(0,TAU),wave,visible:type!=='sub'})}
+const worldSafe=()=>({l:32,r:W-32,t:74,b:H-86});
+function update(dt){if(scene!=='playing')return;elapsed+=dt;waterOffset=(waterOffset+dt*9)%100;shieldCooldown=Math.max(0,shieldCooldown-dt);carrier.invuln=Math.max(0,carrier.invuln-dt);shake=Math.max(0,shake-dt*20);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}
+let mx=0,my=0;if(keys.ArrowLeft||keys.a)mx--;if(keys.ArrowRight||keys.d)mx++;if(keys.ArrowUp||keys.w)my--;if(keys.ArrowDown||keys.s)my++;mx+=stick.x;my+=stick.y;let ml=Math.hypot(mx,my);if(ml>1){mx/=ml;my/=ml}carrier.x+=mx*carrier.speed*dt;carrier.y+=my*carrier.speed*dt;let safe=worldSafe();carrier.x=clamp(carrier.x,safe.l,safe.r);carrier.y=clamp(carrier.y,safe.t,safe.b);if(ml>.1)carrier.angle=Math.atan2(my,mx)+Math.PI/2;
+escorts.forEach((e,i)=>{e.angle+=dt*(.45+(i%2)*.08);let a=e.angle+i*TAU/5;e.x=carrier.x+Math.cos(a)*e.orbit;e.y=carrier.y+Math.sin(a)*e.orbit*.7;if(e.hp>0)e.fire-=dt});
+spawnTimer-=dt;while(spawnQueue.length&&spawnQueue[0].delay<=elapsed){let entry=spawnQueue.shift();spawnEnemy(entry.type)}
+if(spawnQueue.length&&spawnTimer<=0){let e=spawnQueue.shift();spawnEnemy(e.type);spawnTimer=rand(.55,.95)}
+if(fireHeld||keys[' '])fireWeapons(dt);
+if(keys.e)activateShield();keys.e=false;
+for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];e.phase+=dt;e.flash=Math.max(0,e.flash-dt*4);let target=carrier;if(e.type==='plane'){let dx=carrier.x-e.x,dy=carrier.y-e.y;e.x+=(-dy/(Math.hypot(dx,dy)||1)*.34+dx/(Math.hypot(dx,dy)||1)*.65)*e.speed*dt;e.y+=(dx/(Math.hypot(dx,dy)||1)*.34+dy/(Math.hypot(dx,dy)||1)*.65)*e.speed*dt}else if(e.type==='flagship'){let desiredX=W*.5+Math.sin(e.phase*.55)*Math.min(150,W*.22);e.x+=(desiredX-e.x)*dt*.25;e.y=Math.min(H*.25,e.y+e.speed*dt*.3)}else{let dx=carrier.x-e.x,dy=carrier.y-e.y,len=Math.hypot(dx,dy)||1;let wobble=e.type==='sub'?Math.sin(e.phase*2)*.26:Math.sin(e.phase*1.5)*.1;e.x+=(dx/len+Math.cos(e.phase)*wobble)*e.speed*dt;e.y+=(dy/len+Math.sin(e.phase)*wobble)*e.speed*dt}
+e.angle=angle(e,carrier)+Math.PI/2;e.fire-=dt;if(e.fire<=0&&dist(e,carrier)<480){e.fire=e.type==='flagship'?1.25:rand(1.8,3.2);let a=angle(e,carrier),v=e.type==='plane'?190:e.type==='flagship'?145:120;hostileShots.push({x:e.x,y:e.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:e.type==='flagship'?5:3,life:4,color:e.type==='plane'?'#ffbf6e':'#ff8377'})}
+if(e.type==='sub'&&Math.sin(e.phase*1.3)>.65)e.visible=true;else if(e.type==='sub')e.visible=false;
+let contact=dist(e,carrier)<e.r+carrier.r;if(contact&&carrier.invuln<=0){carrier.hp-=e.type==='flagship'?18:10;carrier.invuln=.5;makeBurst(carrier.x,carrier.y,'#ff9b72',12,140);shake=5;if(carrier.hp<=0){carrier.hp=0;gameOver()}}
+}

